use crate::value::check_staged;
use std::fmt::{Debug, Display, Formatter, Result};
use std::str::FromStr;

pub use crate::{
  ArgInfo, AttachedPropertyInfo, AttachedTarget, ContentInfo, ContentMethod, EventInfo, FromUiObject, HasGroup,
  OverrideDefaults, PropertyAccess, PropertyGroup, PropertyGroupInfo, PropertyInfo, PropertyRef, RustExpr, ToRust, TypeInfo,
  TypeKind, UiCollection, UiType, UiValue, ValueError, ValueProviderInfo, Whitespace, WithChildren, check_child, is_a,
  register_type,
};
pub use artic_core::event::Event;
pub use artic_core::property::{
  Affects, AttachedKey, Inheritance, ParseEnumError, Precedence, Property, PropertyKey, PropertyVisitor, SharedKey, inherit,
};
pub use artic_core::tree::{Handle, NodeId, UiTree};
pub use artic_core::{AsChild, AsObject, AsText, Object, RefusesObject, TakesObject, Written};
pub use std::marker::PhantomData;

/// Wraps a property's value type for the check below. `R` is what the value may be: [`AnyValue`]
/// for a property, which can hold a node, or [`PlainValue`] for a value's plain field, which can't,
/// since a value taken out of the tree would leave the node with no owner. Only the check's type
/// decides this, so importing the check's traits can't add the node route to a plain field.
pub struct ValueCheck<T, R>(pub PhantomData<(T, R)>);

/// A property's value: text, an object or a node.
#[derive(Debug)]
pub enum AnyValue {}

/// A value type's plain field: text or an object, never a node.
#[derive(Debug)]
pub enum PlainValue {}

impl<T, R> Debug for ValueCheck<T, R> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ValueCheck")
  }
}

/// What `literal` returns for a property whose value is an element.
const TAKES_AN_ELEMENT: &str = "this property takes an element, not text";

/// What a property's thunks say they were given as text, for [`ValueError::WrongType`].
const TEXT: &str = "text";
/// What a property's thunks say they were given as a node, for [`ValueError::WrongType`].
const AN_ELEMENT: &str = "an element";

/// How a property's thunks turn what the loader holds into the value type `V`. The value check
/// returns it, so a property whose type can't be written in a UI language fails at that one check,
/// and its thunks report the same error at the same place.
#[derive(Debug)]
pub struct ValueOps<V> {
  /// Parses text, or says it didn't parse as `expected`.
  pub parse: fn(&str, &'static str) -> std::result::Result<V, ValueError>,
  /// Takes a node as the value, or refuses it.
  pub node: fn(NodeId, &'static str) -> std::result::Result<V, ValueError>,
}

/// Returns `ops` as is. Generated code passes each check's result through it and names the
/// registry type the check must give for the property's value type `V`: `ValueOps<V>`,
/// `LiteralOps<V>` or `ObjectOps<V>`. So a user trait with the check's method name, in scope where
/// the code expands, can't stand in for the check with a type of its own.
pub fn exactly<T>(ops: T) -> T {
  ops
}

/// How a property's `literal` writes text written in a UI language as Rust, for a value of type
/// `V`. The value check's `literal_ops` gives it.
#[derive(Debug)]
pub struct LiteralOps<V> {
  /// Parses text and writes the value it gives, or says why it can't.
  pub write: fn(&str, &mut RustExpr) -> std::result::Result<(), String>,
  /// The value type the text parses as.
  pub value: PhantomData<V>,
}

/// The `LiteralOps` of a value that is an element: they refuse text.
fn element_literal_ops<V>() -> LiteralOps<V> {
  LiteralOps {
    write: |_, _| Err(TAKES_AN_ELEMENT.to_owned()),
    value: PhantomData,
  }
}

/// Refuses a node: the value is text or an object.
fn not_a_node<V>(_node: NodeId, expected: &'static str) -> std::result::Result<V, ValueError> {
  Err(ValueError::WrongType {
    expected,
    found: AN_ELEMENT,
  })
}

/// Refuses text: the value is an element.
fn not_text<V>(_text: &str, expected: &'static str) -> std::result::Result<V, ValueError> {
  Err(ValueError::WrongType { expected, found: TEXT })
}

/// The value type can be written as text, and written back as Rust.
pub trait ViaFromStr {
  /// The property's value type.
  type Value;

  /// Compiles only for a value type a UI language can write, and gives the thunks' conversions.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<Self::Value>;

  /// Gives the literal's conversion: parse text and write the value it gives.
  fn literal_ops(&self) -> LiteralOps<Self::Value>;
}

impl<T, R> ViaFromStr for ValueCheck<T, R>
where
  T: FromStr + ToRust,
  T::Err: Display,
{
  type Value = T;

  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<T> {
    ValueOps {
      parse: |text, expected| {
        text.parse().map_err(|error: T::Err| ValueError::Parse {
          expected,
          message: error.to_string(),
        })
      },
      node: not_a_node,
    }
  }

  fn literal_ops(&self) -> LiteralOps<T> {
    LiteralOps {
      write: |text, out| {
        let value: T = text.parse().map_err(|error: T::Err| error.to_string())?;
        value.to_rust(out);
        Ok(())
      },
      value: PhantomData,
    }
  }
}

/// The value type is itself a UI type, written as an object.
pub trait ViaUiType {
  /// The property's value type.
  type Value;

  /// Compiles only for a value type a UI language can write. Text and a node are both refused:
  /// the value is an object, which the loader moves in as one.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<Self::Value> {
    ValueOps {
      parse: not_text,
      node: not_a_node,
    }
  }

  /// Gives a literal that refuses text: the value is an element.
  fn literal_ops(&self) -> LiteralOps<Self::Value> {
    element_literal_ops()
  }
}

impl<T: UiType, R> ViaUiType for &ValueCheck<T, R> {
  type Value = T;
}

/// The value is a child element, filled in by the element written inside.
pub trait ViaChild {
  /// Compiles only for a value type a UI language can write. Text is refused; a node is the value.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<NodeId> {
    ValueOps {
      parse: not_text,
      node: |node, _| Ok(node),
    }
  }

  /// Gives a literal that refuses text: the value is an element.
  fn literal_ops(&self) -> LiteralOps<NodeId> {
    element_literal_ops()
  }
}

impl ViaChild for &&ValueCheck<NodeId, AnyValue> {}

/// The conversions of a value written as the marker `Self` says, for the value type `V`: generated
/// code names them as `<<V as Written>::As as Route<V>>`, so the value type alone picks them, and
/// no method lookup or trait in scope where the code expands takes part.
#[diagnostic::on_unimplemented(
  message = "`{V}` can't be written the way its `Written` impl says",
  note = "a value written as text (`AsText`) implements `FromStr` and `ToRust`, one written as an object (`AsObject`) derives `UiType`, and only `NodeId` is written as a child (`AsChild`)"
)]
pub trait Route<V> {
  /// Gives the thunks' conversions from text and from a node.
  fn value_ops() -> ValueOps<V>;

  /// Gives the literal's conversion: parse text and write the value it gives, or refuse it.
  fn literal_ops() -> LiteralOps<V>;
}

impl<V> Route<V> for AsText
where
  V: FromStr + ToRust,
  V::Err: Display,
{
  fn value_ops() -> ValueOps<V> {
    ValueOps {
      parse: |text, expected| {
        text.parse().map_err(|error: V::Err| ValueError::Parse {
          expected,
          message: error.to_string(),
        })
      },
      node: not_a_node,
    }
  }

  fn literal_ops() -> LiteralOps<V> {
    LiteralOps {
      write: |text, out| {
        let value: V = text.parse().map_err(|error: V::Err| error.to_string())?;
        value.to_rust(out);
        Ok(())
      },
      value: PhantomData,
    }
  }
}

/// Text and a node are both refused: the value is an object, which the loader moves in as one.
impl<V: UiType> Route<V> for AsObject {
  fn value_ops() -> ValueOps<V> {
    ValueOps {
      parse: not_text,
      node: not_a_node,
    }
  }

  fn literal_ops() -> LiteralOps<V> {
    element_literal_ops()
  }
}

/// Text is refused; a node is the value.
impl Route<NodeId> for AsChild {
  fn value_ops() -> ValueOps<NodeId> {
    ValueOps {
      parse: not_text,
      node: |node, _| Ok(node),
    }
  }

  fn literal_ops() -> LiteralOps<NodeId> {
    element_literal_ops()
  }
}

/// The routes a value type's plain field may take: text or an object, never a node, since a value
/// taken out of the tree would leave the node with no owner.
#[diagnostic::on_unimplemented(
  message = "a value's `#[ui]` fields are plain data, not a `NodeId`",
  label = "its node would stay in the tree with no owner once the value is taken out"
)]
pub trait PlainRoute<V>: Route<V> {
  /// Gives the thunks' conversions, as [`Route::value_ops`] does, for a plain field.
  fn plain_value_ops() -> ValueOps<V> {
    Self::value_ops()
  }
}

impl<V> PlainRoute<V> for AsText where AsText: Route<V> {}

impl<V> PlainRoute<V> for AsObject where AsObject: Route<V> {}

/// How a staged object becomes a value of type `V`, as the marker `Self` says: generated code
/// names it as `<<V as Written>::FromObject as ObjectRoute<V>>`.
pub trait ObjectRoute<V> {
  /// Gives the conversion that takes the staged object out of the tree as the value of the
  /// owner's property, or refuses it.
  fn object_ops() -> ObjectOps<V>;
}

impl<V: FromUiObject> ObjectRoute<V> for TakesObject {
  fn object_ops() -> ObjectOps<V> {
    ObjectOps {
      take: |tree, owner, object, _| {
        check_staged(tree, owner, object)?;
        V::from_object(tree, object)
      },
    }
  }
}

/// The staged object is taken out, so none is left behind, and refused.
impl<V> ObjectRoute<V> for RefusesObject {
  fn object_ops() -> ObjectOps<V> {
    ObjectOps {
      take: |tree, owner, object, expected| {
        check_staged(tree, owner, object)?;
        drop(tree.take(object));
        Err(ValueError::WrongType {
          expected,
          found: AN_OBJECT,
        })
      },
    }
  }
}

/// What a property's `set_object` says it was given when its value type isn't taken from an object.
const AN_OBJECT: &str = "an object";

/// Wraps a property's value type to choose how a staged object becomes it.
pub struct ObjectCheck<T>(pub PhantomData<T>);

impl<T> Debug for ObjectCheck<T> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ObjectCheck")
  }
}

/// How a property's `set_object` takes a staged object as a value of type `V`. The object check
/// gives it.
#[derive(Debug)]
pub struct ObjectOps<V> {
  /// Takes the staged `object` out of the tree as the value of `owner`'s property, or refuses it
  /// as `expected`.
  pub take: fn(&mut UiTree, NodeId, NodeId, &'static str) -> std::result::Result<V, ValueError>,
}

/// The value type is taken from a staged object.
pub trait ViaFromUiObject {
  /// The property's value type.
  type Value;

  /// Gives the conversion that takes the staged object out of the tree as the value of the owner's
  /// property.
  fn object_ops(&self) -> ObjectOps<Self::Value>;
}

impl<T: FromUiObject> ViaFromUiObject for ObjectCheck<T> {
  type Value = T;

  fn object_ops(&self) -> ObjectOps<T> {
    ObjectOps {
      take: |tree, owner, object, _| {
        check_staged(tree, owner, object)?;
        T::from_object(tree, object)
      },
    }
  }
}

/// The value type isn't taken from an object: the staged object is taken out and refused.
pub trait NotFromObject {
  /// The property's value type.
  type Value;

  /// Gives the conversion that takes the staged object out of the tree, so none is left behind,
  /// and refuses it as the value of the owner's property.
  fn object_ops(&self) -> ObjectOps<Self::Value> {
    ObjectOps {
      take: |tree, owner, object, expected| {
        check_staged(tree, owner, object)?;
        drop(tree.take(object));
        Err(ValueError::WrongType {
          expected,
          found: AN_OBJECT,
        })
      },
    }
  }
}

impl<T> NotFromObject for &ObjectCheck<T> {
  type Value = T;
}

/// Sets a value type's plain field, which `field` reaches in a `node` of the type `O`: the end of
/// a value type's [`PropertyAccess`] setters. A value has no precedence levels.
pub fn set_field<O: Object, T>(
  tree: &mut UiTree,
  node: NodeId,
  field: fn(&mut O) -> &mut T,
  value: T,
) -> std::result::Result<(), ValueError> {
  let owner = tree.get_as_mut::<O>(node).ok_or(ValueError::WrongNode)?;
  *field(owner) = value;
  Ok(())
}

/// Sets `value` at `level` on `node`'s property of the kind `key`: the end of every
/// [`PropertyAccess`] setter.
pub fn set_property<T>(
  tree: &UiTree,
  node: NodeId,
  key: &'static PropertyKey<T>,
  level: Precedence,
  value: T,
) -> std::result::Result<(), ValueError>
where
  T: PartialEq + 'static,
{
  crate::access::property_of(tree, node, key)?.set_at(level, value);
  Ok(())
}

/// Empties `level` of `node`'s property of the kind `key`: [`PropertyAccess::clear`].
pub fn clear_property<T>(
  tree: &UiTree,
  node: NodeId,
  key: &'static PropertyKey<T>,
  level: Precedence,
) -> std::result::Result<(), ValueError>
where
  T: PartialEq + 'static,
{
  crate::access::property_of(tree, node, key)?.clear(level);
  Ok(())
}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
///
/// A user trait with the check's method name, in scope where it expands, can't stand in for the
/// check with a type of its own:
///
/// ```compile_fail,E0308
/// struct Mine;
///
/// trait Lookalike {
///   fn literal_ops(&self) -> Mine {
///     Mine
///   }
/// }
///
/// impl<T> Lookalike for T {}
///
/// let _ = artic_registry::__private::literal!(f32);
/// ```
#[cfg(feature = "literals")]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::Some({
      fn literal(text: &str, out: &mut $crate::RustExpr) -> ::core::result::Result<(), ::std::string::String> {
        use $crate::__private::{ViaChild as _, ViaFromStr as _, ViaUiType as _};
        let ops = $crate::__private::exactly::<$crate::__private::LiteralOps<$value>>(
          (&&$crate::__private::ValueCheck::<$value, $crate::__private::AnyValue>($crate::__private::PhantomData))
            .literal_ops(),
        );
        (ops.write)(text, out)
      }
      literal as $crate::WriteLiteral
    })
  };
}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
#[cfg(not(feature = "literals"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::None
  };
}

pub use crate::__literal as literal;

/// What `PropertyInfo::access` holds for a property whose thunks are `$access`: `Some` with the
/// `access` feature, `None` without, so an app without a runtime loader keeps no thunks.
#[cfg(feature = "access")]
#[doc(hidden)]
#[macro_export]
macro_rules! __access {
  ($access:expr) => {
    ::core::option::Option::Some($access)
  };
}

/// What `PropertyInfo::access` holds for a property whose thunks are `$access`: `Some` with the
/// `access` feature, `None` without, so an app without a runtime loader keeps no thunks.
#[cfg(not(feature = "access"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __access {
  ($access:expr) => {
    ::core::option::Option::None
  };
}

pub use crate::__access as access;

/// The function `AttachedPropertyInfo::literal` holds for an attached property of type
/// `Option<$value>`: it writes the `$value` text gives inside `Some(...)`, since the owner's setter
/// takes the whole `Option`. `None` without the `literals` feature.
#[cfg(feature = "literals")]
#[doc(hidden)]
#[macro_export]
macro_rules! __optional_literal {
  ($value:ty) => {
    ::core::option::Option::Some({
      fn literal(text: &str, out: &mut $crate::RustExpr) -> ::core::result::Result<(), ::std::string::String> {
        let inner = $crate::__literal!($value).expect("the literals feature gives every value a literal");
        out.raw("::core::option::Option::Some(");
        inner(text, out)?;
        out.raw(")");
        ::core::result::Result::Ok(())
      }
      literal as $crate::WriteLiteral
    })
  };
}

/// The function `AttachedPropertyInfo::literal` holds for an attached property of type
/// `Option<$value>`: `None` without the `literals` feature.
#[cfg(not(feature = "literals"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __optional_literal {
  ($value:ty) => {
    ::core::option::Option::None
  };
}

pub use crate::__optional_literal as optional_literal;

/// Whether `a` and `b` are the same text, in const code.
const fn same_text(a: &str, b: &str) -> bool {
  let (a, b) = (a.as_bytes(), b.as_bytes());
  if a.len() != b.len() {
    return false;
  }
  let mut index = 0;
  while index < a.len() {
    if a[index] != b[index] {
      return false;
    }
    index += 1;
  }
  true
}

/// Whether a compiled view's code type is `path`, in const code.
pub const fn same_code_type(code_type: Option<&str>, path: &str) -> bool {
  match code_type {
    Some(code_type) => same_text(code_type, path),
    None => false,
  }
}

/// `name` without a raw identifier's `r#`, which a field's method name doesn't have, in const
/// code.
const fn unraw(name: &str) -> &str {
  match name.as_bytes() {
    [b'r', b'#', ..] => name.split_at(2).1,
    _ => name,
  }
}

/// Whether a group's `properties` hold a field named `name`, with or without `r#` on either side,
/// since `r#width` and `width` both get a method named `width`.
pub const fn group_has_field(properties: &[PropertyInfo], name: &str) -> bool {
  let mut index = 0;
  while index < properties.len() {
    if same_text(unraw(properties[index].field), unraw(name)) {
      return true;
    }
    index += 1;
  }
  false
}

/// Whether two groups' `properties` hold a field of one name.
pub const fn groups_share_field(a: &[PropertyInfo], b: &[PropertyInfo]) -> bool {
  let mut index = 0;
  while index < a.len() {
    if group_has_field(b, a[index].field) {
      return true;
    }
    index += 1;
  }
  false
}

/// Compiles only if `T` is a property group.
pub const fn assert_property_group<T: PropertyGroup>() {}

/// The content a flattened group gives the type that holds it in `field`.
pub const fn group_content(field: &'static str, info: Option<&'static PropertyInfo>) -> Option<ContentInfo> {
  match info {
    Some(info) => Some(ContentInfo::Property(PropertyRef {
      group: Some(field),
      info,
    })),
    None => None,
  }
}

/// The one content candidate that is set, if any.
///
/// # Panics
///
/// At compile time, when more than one is set: a type has at most one content member, counting the
/// groups it flattens.
pub const fn one_content(candidates: &[Option<ContentInfo>]) -> Option<ContentInfo> {
  let mut found = None;
  let mut index = 0;
  while index < candidates.len() {
    if let Some(candidate) = candidates[index] {
      assert!(
        found.is_none(),
        "a type has at most one `#[ui(content)]` member, counting the groups it flattens"
      );
      found = Some(candidate);
    }
    index += 1;
  }
  found
}

/// A collection a value's content may be: values taken from staged objects, never child nodes,
/// which taking the value out of the tree would free.
#[diagnostic::on_unimplemented(
  message = "a value's content is a collection of values, not `{Self}`",
  label = "a value can't hold child nodes",
  note = "use `Vec<T>` or `Arc<[T]>` of a value type, such as `Vec<GradientStop>`"
)]
pub trait ValueCollection {}

impl<T: FromUiObject> ValueCollection for Vec<T> {}

impl<T: FromUiObject + Clone> ValueCollection for std::sync::Arc<[T]> {}

/// Accepts only a [`ValueCollection`], so a value's generated code fails to compile on any other
/// content.
pub const fn value_collection<C: ValueCollection>() {}

/// A key a field may name its own default beside: a property key, through any number of
/// references. An attached key brings its own default, and two could disagree.
#[diagnostic::on_unimplemented(
  message = "`default` can't go beside an attached key",
  label = "this attached key already gives the field its default",
  note = "remove `default = ...`; the field starts at the attached property's default"
)]
pub trait TakesDefault {}

impl<T> TakesDefault for PropertyKey<T> {}

impl<K: TakesDefault + ?Sized> TakesDefault for &K {}

/// Returns `value`, the default a field names beside `key`, once the compiler has checked that
/// `key` may take one.
pub fn default_beside<K: TakesDefault + ?Sized, T>(key: &K, value: T) -> T {
  let _ = key;
  value
}

#[cfg(test)]
mod tests {
  use super::*;

  /// A group property whose field is written `field`.
  fn property(field: &'static str) -> PropertyInfo {
    PropertyInfo::new("Width", field, "f32").with_affects(Affects::LAYOUT)
  }

  // A raw field and a plain one of the same name clash, either way round, since both get the
  // same method; another name doesn't.
  #[test]
  fn group_field_check_ignores_raw_spelling() {
    for (group, own) in [("width", "r#width"), ("r#width", "width"), ("r#width", "r#width")] {
      assert!(group_has_field(&[property(group)], own), "{group} and {own}");
    }
    assert!(!group_has_field(&[property("width")], "r#height"));
    assert!(!group_has_field(&[property("r")], "r#"));
  }

  #[derive(Debug)]
  struct Gauge;

  impl UiType for Gauge {
    const TYPE_INFO: &'static TypeInfo = &GAUGE;
  }

  static GAUGE: TypeInfo = TypeInfo::node("Gauge", "tests::Gauge", |_| false);

  impl Object for Gauge {
    fn visit_properties(&self, _visitor: &mut PropertyVisitor<'_>) {}
  }

  impl Written for Gauge {
    type As = AsObject;
    type FromObject = RefusesObject;
  }

  /// A tree holding two gauges: an owner, and a detached one to stage or set as a node.
  fn two_gauges() -> (UiTree, NodeId, NodeId) {
    let mut tree = UiTree::new();
    let owner = tree.alloc(Box::new(Gauge));
    let other = tree.alloc(Box::new(Gauge));
    (tree, owner, other)
  }

  // Text parses through a text value's route, which refuses a node.
  #[test]
  fn text_route_parses_and_refuses_a_node() {
    let (_, _, node) = two_gauges();
    let ops = <<f32 as Written>::As as Route<f32>>::value_ops();

    assert_eq!((ops.parse)("1.5", "f32"), Ok(1.5));
    assert_eq!(
      (ops.node)(node, "f32"),
      Err(ValueError::WrongType {
        expected: "f32",
        found: "an element",
      })
    );
  }

  // An object's route refuses both text and a node: the loader moves the object in as one.
  #[test]
  fn object_route_refuses_text_and_a_node() {
    let (_, _, node) = two_gauges();
    let ops = <<Gauge as Written>::As as Route<Gauge>>::value_ops();

    assert_eq!(
      (ops.parse)("1.5", "Gauge").err(),
      Some(ValueError::WrongType {
        expected: "Gauge",
        found: "text",
      })
    );
    assert_eq!(
      (ops.node)(node, "Gauge").err(),
      Some(ValueError::WrongType {
        expected: "Gauge",
        found: "an element",
      })
    );
  }

  // A child's route takes the node as the value and refuses text.
  #[test]
  fn child_route_takes_a_node_and_refuses_text() {
    let (_, _, node) = two_gauges();
    let ops = <<NodeId as Written>::As as Route<NodeId>>::value_ops();

    assert_eq!((ops.node)(node, "NodeId"), Ok(node));
    assert_eq!(
      (ops.parse)("1.5", "NodeId"),
      Err(ValueError::WrongType {
        expected: "NodeId",
        found: "text",
      })
    );
  }

  // A text value's literal writes the Rust the text parses to; an object's and a child's refuse
  // text.
  #[test]
  fn literal_routes_write_text_and_refuse_elements() {
    let mut out = RustExpr::new();
    (<<f32 as Written>::As as Route<f32>>::literal_ops().write)("1.5", &mut out).expect("a number");
    assert_eq!(out.take(), "1.5_f32");

    let object = <<Gauge as Written>::As as Route<Gauge>>::literal_ops().write;
    let child = <<NodeId as Written>::As as Route<NodeId>>::literal_ops().write;
    for write in [object, child] {
      assert_eq!(write("1.5", &mut RustExpr::new()), Err(TAKES_AN_ELEMENT.to_owned()));
    }
  }

  // A value type not taken from objects takes the staged object out of the tree, so none is left
  // behind, and refuses it.
  #[test]
  fn refused_object_is_taken_out_and_refused() {
    let (mut tree, owner, object) = two_gauges();
    let ops = <<f32 as Written>::FromObject as ObjectRoute<f32>>::object_ops();

    assert_eq!(
      (ops.take)(&mut tree, owner, object, "f32"),
      Err(ValueError::WrongType {
        expected: "f32",
        found: "an object",
      })
    );
    assert!(!tree.contains(object));
    assert!(tree.contains(owner));
  }

  // The check resolves for a FromStr type, a UI type and a child node, and a plain field's check
  // for the first two. A type that is none of them fails to compile, which the derive's
  // compile-fail tests cover.
  #[test]
  #[allow(
    clippy::needless_borrow,
    reason = "the extra references pick the matching check, as in generated code"
  )]
  fn value_check_accepts_text_object_and_child_values() {
    (&&ValueCheck::<f32, AnyValue>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<Gauge, AnyValue>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<NodeId, AnyValue>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<f32, PlainValue>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<Gauge, PlainValue>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
  }

  // A code type matches only the same whole path, and a view without one matches nothing.
  #[test]
  fn same_code_type_compares_whole_paths() {
    assert!(same_code_type(Some("app::views::LoginView"), "app::views::LoginView"));
    assert!(!same_code_type(Some("app::views::LoginView"), "app::views::LoginViews"));
    assert!(!same_code_type(Some("other::views::LoginView"), "app::views::LoginView"));
    assert!(!same_code_type(None, "app::views::LoginView"));
  }
}
